"""Constants of the chunk format (`chunk 0.1`, see 1008_worldgen.md section 1). Changing anything that alters generated bytes
means bumping GENERATOR_VERSION and regenerating tests/golden/worldgen_*."""
from __future__ import annotations

CHUNK_SPEC = "0.1"
GENERATOR_VERSION = "0.1.0"

CHUNK_TILES = 32
UNITS_PER_TILE = 8
CHUNK_UNITS = CHUNK_TILES * UNITS_PER_TILE      # 256
TILE_PX = 48
APRON = 1                                        # tiles of neighbourhood sampled around the chunk for edge masks
POSITION_QUANTUM = 16                            # positions are multiples of 1/16 unit
ACTOR_RADIUS = 2.4
WALL_HEIGHT = 2.4

REGION_CHUNKS = 8                                # coarse region grid for features larger than a chunk
REGION_TILES = REGION_CHUNKS * CHUNK_TILES       # 256
MAX_FEATURE_RADIUS = 40                          # tiles; no region feature reaches further than this from its centre

MAX_ENTITIES_PER_CHUNK = 16
MAX_SPAWN_ENTRIES = 4
MAX_PROPS_PER_CHUNK = 640

QUADRANT_TILES = 16                              # resource aggregation cell (a chunk has 2 x 2)

FIELD_BITS = 12
FIELD_MAX = (1 << FIELD_BITS) - 1               # 4095

# Layer palette ids (stable per generator version).
TERRAIN_GRASS, TERRAIN_SAND, TERRAIN_WATER, TERRAIN_ROCK, TERRAIN_PAVING = 1, 2, 3, 4, 5
FOOT_WATER, FOOT_ROCK, FOOT_RUIN = 1, 2, 3

# Semantic biome ids (data.biome).
B_VOID, B_WATER, B_SHORE, B_PLAINS, B_FOREST, B_MEADOW, B_HIGHLAND, B_DESERT, B_WETLAND, B_RIVER, B_FORD, B_RUIN, B_PEAK = range(13)
BIOME_NAMES = ("void", "water", "shore", "plains", "forest", "meadow", "highland", "desert", "wetland", "river", "ford", "ruin", "peak")
